return static function():void{/** @var Database $database */$database=require dirname(__DIR__,2).'/bootstrap/database.php';$pdo=$database->connection();$pdo->beginTransaction();try{$suffix=bin2hex(random_bytes(5));$userId=(int)$pdo->query('SELECT id FROM users WHERE is_active=1 AND deleted_at IS NULL ORDER BY id LIMIT 1')->fetchColumn();$staffIds=array_map('intval',$pdo->query('SELECT id FROM staff WHERE status="published" AND deleted_at IS NULL ORDER BY id LIMIT 2')->fetchAll(PDO::FETCH_COLUMN));$typeId=(int)$pdo->query('SELECT id FROM publication_types ORDER BY display_order,id LIMIT 1')->fetchColumn();if($userId<1||count($staffIds)<2||$typeId<1)throw new RuntimeException('Publication flow prerequisites are missing.');$users=new UserRepository($database);$authorization=new AuthorizationService($users);$scope=new DepartmentScopeService($users,$authorization);$repo=new PublicationRepository($database,$scope);$service=new PublicationService($repo,$authorization,new AuditService($database));$validator=new PublicationValidator($repo);$input=['publication_type_id'=>(string)$typeId,'title'=>'Transactional Publication '.$suffix,'slug'=>'transactional-publication-'.$suffix,'abstract'=>'A publication created inside a rolled-back integration test.','journal_name'=>'Journal of Transactional Research','publisher'=>'FAST Test Press','publication_year'=>'2026','publication_date'=>'2026-03-01','volume'=>'1','issue'=>'2','page_range'=>'1-10','doi'=>'10.9999/'.$suffix,'isbn'=>'','external_url'=>'https://example.invalid/publication','access_type'=>'open_access','citation_text'=>'Test Author (2026). Transactional Publication.','project_id'=>'','research_unit_id'=>''];$validated=$validator->validate($input);if($validated['errors']!==[])throw new RuntimeException('Valid publication rejected: '.json_encode($validated['errors']));$id=$service->create($validated['data'],$validated['project_id'],$validated['research_unit_id'],$userId,'127.0.0.17','FAST publication integration test');$service->addAuthor($id,$staffIds[0],'','','',1,true,$userId,'127.0.0.17','FAST publication integration test');$service->addAuthor($id,null,'External Author','Partner University','0000-0002-1825-0097',2,false,$userId,'127.0.0.17','FAST publication integration test');$authors=$repo->authors($id);if(count($authors)!==2||(int)$authors[0]['staff_id']!==$staffIds[0]||$authors[1]['external_author_name']!=='External Author')throw new RuntimeException('Ordered internal/external authors were not stored.');$service->publishDraft($id,$userId,'Complete publication published','127.0.0.17','FAST publication integration test');$public=$repo->findPublishedBySlug($input['slug']);if(!is_array($public)||$public['status']!=='published')throw new RuntimeException('Publication was not publicly retrievable.');$staffPublications=$repo->staffPublications($staffIds[0]);if(!array_filter($staffPublications,static fn(array$p):bool=>$p['slug']===$input['slug']))throw new RuntimeException('Published record was not returned on its staff author profile.');$updated=$validated['data'];$updated['abstract']='Updated while remaining published.';$service->updatePublished($id,$updated,null,null,$userId,'Live citation correction','127.0.0.17','FAST publication integration test');$service->addAuthor($id,$staffIds[1],'','','',2,false,$userId,'127.0.0.17','FAST publication integration test');$public=$repo->findPublishedBySlug($input['slug']);if(!is_array($public)||$public['abstract']!==$updated['abstract']||count($repo->authors($id,true))!==3)throw new RuntimeException('Published publication/author changes did not remain public.');if($service->transition($id,'archived',$userId,'Test archive','127.0.0.17','FAST publication integration test')!=='archived'||$repo->findPublishedBySlug($input['slug'])!==null)throw new RuntimeException('Archived publication remained public.');if($service->transition($id,'restored',$userId,'Test restore','127.0.0.17','FAST publication integration test')!=='draft')throw new RuntimeException('Archived publication did not restore to draft.');}finally{if($pdo->inTransaction())$pdo->rollBack();}};
